mapper.select:
SELECT gc.classify_id, gc.shop_id, gci.classify_name, gci.language_type, gci.language_name FROM goods_classify AS gc LEFT JOIN goods_classify_i18n AS gci ON gc.classify_id = gci.classify_id where gc.classify_id = #{classifyId}
and (gc.shop_id = #{shopId} OR gc.shop_id = 0)
and gci.language_type = #{languageType}

SELECT gc.classify_id, gc.shop_id, gci.classify_name, gci.language_type, gci.language_name, gs.shop_name FROM goods_classify AS gc LEFT JOIN goods_classify_i18n AS gci ON gc.classify_id = gci.classify_id LEFT JOIN goods_shop gs ON gc.shop_id = gs.shop_id
and (gc.shop_id = #{shopId} or gc.shop_id = 0)
and gci.language_type = #{languageType}

SELECT gsr.sales AS sales, gsr.inventory AS inventory, g.goods_id, g.classify_id, g.goods_cover, g.goods_picture, g.create_time, g.sales_volume, g.`status`, g.pack_money, g.goods_money, g.original_money, g.shop_id, gi.goods_name, gi.goods_synopsis, gi.goods_describe, gi.goods_label, gi.language_type, gi.language_name FROM goods_shop_relevancy AS gsr LEFT JOIN goods AS g ON gsr.goods_id = g.goods_id LEFT JOIN goods_i18n AS gi ON g.goods_id = gi.goods_id WHERE gsr.shop_id = #{shopId} AND g.classify_id = #{classifyId} AND gsr.`STATUS` = 0
AND gi.language_type = #{languageType}
ORDER BY g.classify_id ASC
